"@H1|۳. هویت: یک پالایشگاه روغن، چهار شرکت فرعی",
"@P|نفت سپاهان در سال ۱۳۸۱ در اصفهان تأسیس شد و فعالیت خود را بر «تولید روغن پایه و فرآورده‌های مرتبط» متمرکز کرد (اس۰۱، اس۱۱). و «پالایشگاه» در «شاهین‌شهر» اصفهان است و «دفتر مرکزی» در تهران. و «مدل» «شرکت»، «پالایش روغن» است، نه «پالایش نفت خام».",
"@P|**نکتهٔ مدل.** خوراک شپاس «وکیوم باتوم» است که از «پالایش نفت اصفهان» می‌آید (اس۱۲). و «شپنا» هم «سهامدار ۱۷٫۳ درصدی» است و هم «تأمین‌کنندهٔ اصلی». و این «دو نقش»، «یک» «وابستگی» می‌سازد که در «بحران» «قیمت» و «تأمین» «دیده» می‌شود.",
"@P|**نکتهٔ ظرفیت.** «تولید سالانه حدود ۷۰۰ هزار تن» است: «۶۰۰ هزار تن روغن پایه» و «۱۰۰ هزار تن محصولات نهایی» (اس۰۱، اس۱۱). و «ظرفیت اسمی» «روغن پایه» «نزدیک به ۴۰۰ هزار تن» است و «بیش از ۳۰۰ هزار تن» «فرآورده‌های ویژه» و «پارافین» و «اسلاک واکس» (اس۱۳). و «دو» «عدد» «دو» «تعریف» است.",
"@P|**نکتهٔ شرکت‌های فرعی.** «کیمیا اسپیدی قشم» (توزیع و پخش)، «اوجان شیمی تبریز»، «پارافین‌سازی اشتهارد» و «آریا سولار» چهار «فرعی» «شناخته‌شده» است (اس۰۱، اس۱۴). و «گروه» با «چهار» «فرعی» «یک» «زنجیرهٔ» «کامل» «می‌سازد»: «تولید، بسته‌بندی، توزیع و فروش». و «زنجیره» «در» «روایت» «شرکت» «دیده» «نمی‌شود».",
"@P|**نکتهٔ برندها.** «اسپیدی» و «مگلوب» دو «برند» «مصرفی» است که «کیمیا اسپیدی» «توزیع» می‌کند و «بیش از ۳۰ هزار اتوسرویس» را «پوشش» می‌دهد که «۲۰ هزار» «دائمی» «سفارش» «می‌دهند» (اس۱۴). و «این» «عدد» «قوی‌ترین» «سرمایهٔ» «برند» «شرکت» است و «در» «هیچ» «گزارش» «رسمی» «تکرار» «نمی‌شود».",
"@P|**نکتهٔ مالکیت.** «تابان فردا» حدود «۶۶ تا ۶۷٫۵۶ درصد» و «پالایش نفت اصفهان» «۱۷٫۳ درصد» و «صندوق بازنشستگی کشوری» «۲٫۷۶ درصد» (اس۰۲، اس۰۳، اس۰۴). و «شناوری» حدود «۱۱ درصد» است (اس۰۳). و «شناوری کم» یعنی «کشف قیمت» «ضعیف» و «نقدشوندگی» «کم» — و «روایت» «شرکت» «بیشتر» «برای» «سهامدار» «عمده» «ساخته» «می‌شود»، نه «بازار».",
"@P|**نکتهٔ سرمایه‌گذاری متقابل.** شپاس «حدود ۲٫۵۹ درصد» از «شپنا» را «به» «بهای» «تمام‌شدهٔ» «۵۴۱ میلیارد تومان» «دارد» و «ارزش روز» آن «بیش از ۵ هزار میلیارد تومان» «برآورد» «شد» (اس۰۳). و «یک» «منبع» «دیگر» «۳٫۵ درصد» «می‌گوید» (اس۰۴). و «تفاوت»، «تعارض» «ثبت‌شده» است.",
"@P|**خوانش ما.** هویت شپاس «روغن پایه + شبکهٔ توزیع» است، نه «قیر» و نه «روغن موتور خالص». و «هویت» «در» «بازار» «به» «درستی» «شناخته» «نمی‌شود»: «بسیاری» «آن» «را» «با» «نفت سپاهانِ» «روغن» «می‌شناسند» و «بسیاری» «با» «فولاد» «سپاهان» «اشتباه» «می‌گیرند».",
