"@P|**تلهٔ سوم: سپاهان پلی‌اکریل.** «سپاهان» «پلی‌اکریل» «یک» «شرکت» «پتروشیمی» «است» و «محصول» «آن» «الیاف» «و» «پلیمر» است. و «هیچ» «نسبت» «سهامداری» «با» «نفت» «سپاهان» «ندارد». و «نام» «مشترک» «کافی» «نیست».",
"@P|**تلهٔ چهارم: پالایش نفت اصفهان.** «شپنا» «سهامدار» «۱۷٫۳ درصدی» «و» «تأمین‌کنندهٔ» «خوراک» «است»؛ «همسایه» «و» «شریک»، «نه» «خودِ» «پرونده». و «اعداد» «شپنا» «به» «شپاس» «نسبت» «داده» «نشود».",
"@P|**تلهٔ پنجم: اسپیدی و مگلوب.** «اسپیدی» «برند» «فروش» «روغن» «است» و «کیمیا» «اسپیدی» «قشم» «شرکت» «توزیع» «فرعی». و «اسپیدی» «یک» «شرکت» «مستقل» «نیست»؛ «برند» «است». و «اشتباه» «رایج»: «اسپیدی» «را» «شرکت» «بدانیم».",
"@P|**تلهٔ ششم: پارس و بهران و ایرانول.** «نفت پارس»، «نفت بهران» و «نفت ایرانول» «سه» «رقیب» «بورسی» «هستند» و «اعداد» «آن‌ها» «به» «شپاس» «نسبت» «داده» «نشود». و «ایرانول» «پروندهٔ» «۱۳۰» «است» و «مقایسه» «در» «بخش» «۳۹» «آمده».",
"@P|**تلهٔ هفتم: «شپاس».** «شپاس» «نماد» «نفت» «پاسارگاد» «است» — «شرکت» «قیر» — «و» «هیچ» «ارتباطی» «با» «شسپا» «ندارد». و «دو» «نماد» «در» «یک» «هفته» ««شپ» «دارند» و «در» «دو» «صنعت» «متفاوت» «فعال‌اند». و «این» «نزدیکی» «نماد» «یک» «دام» «واقعی» «برای» «خبرنگار» «است».",
"@P|**نکتهٔ چرا مهم است.** «خدمت روابط عمومی» «روی» «هویت» «سوار» «می‌شود». و «اگر» «هویت» «در» «بیرون» «مشوش» «باشد»، «هر» «خدمت» «با» «نویز» «شروع» «می‌شود». و «رفع» «ابهام» «نام» «یک» «صفحه» «است»: «نفت سپاهان (شسپا): روغن پایه، نه قیر، نه فولاد».",
